                requestId
              );
              logger.error(
                `Failed running afterLiveQueryEvent on class ${className} for event ${res.event} with session ${res.sessionToken} with:\n Error: ` +
                  JSON.stringify(error)
              );
            }
          );
      }
    }
  }
}

