		proxyRequest.Body = ioutil.NopCloser(strings.NewReader(requestData.Data))
		proxyRequest.Body.Close()
	}

	var client http.Client
	var proxyResponse *http.Response
	proxyResponse, err := client.Do(&proxyRequest)

