def where_in(values: list[Any], mark: str = "'") -> str:
    """
    Given a list of values, build a parenthesis list suitable for an IN expression.

        >>> where_in([1, "b", 3])
        (1, 'b', 3)

    """

    def quote(value: Any) -> str:
        if isinstance(value, str):
            value = value.replace(mark, mark * 2)
            return f"{mark}{value}{mark}"
        return str(value)

    joined_values = ", ".join(quote(value) for value in values)
    return f"({joined_values})"

def visit_Call(self, node):
    """ A couple function calls are supported: bson's ObjectId() and
    datetime().
    """
    if isinstance(node.func, ast.Name):
        expr = None
        if node.func.id == 'ObjectId':
            expr = "('" + node.args[0].s + "')"
        elif node.func.id == 'datetime':
            values = []
            for arg in node.args:
                values.append(str(arg.n))
            expr = "(" + ", ".join(values) + ")"
        if expr:
            self.current_value = eval(node.func.id + expr)

