func isSymbolLink(filepath string) (bool, error) {
	fi, err := os.Lstat(path.Clean(filepath))
	if err != nil {
		return false, err
	}
	if fi.Mode()&os.ModeSymlink != 0 {
		return true, nil
	}
	return false, nil
}

