        if verbose:
            print(f"{bucket.name} | Downloading {obj.key}")
    dest_file_path.parent.mkdir(parents=True, exist_ok=True)  # Equivalent to `mkdir -p`
    self.s3_client.download_file(bucket.name, obj.key, str(dest_file_path))

