            bucket: str,
            region: Optional[str] = None,
            access_key_id: Optional[str] = None,
            secret_key: Optional[str] = None,
            session_token: Optional[str] = None,
            endpoint_url: Optional[str] = None,
            prefix: Optional[str] = None,
):
